package com.bank.chain;

import java.math.BigDecimal;

class PendingChain {
    private TransactionNode head;
    private TransactionNode tail;
    private int size = 0;        // maintained count for O(1) length

    void append(BigDecimal amount) {
        TransactionNode node = new TransactionNode(amount);
        if (head == null) {
            head = tail = node;
        } else {
            tail.next = node;
            tail = node;
        }
        size++;                  // keep the maintained count in sync
    }

    // O(n): walk the chain counting nodes.
    int lengthByTraversal() {
        int count = 0;
        TransactionNode current = head;
        while (current != null) {
            count++;
            current = current.next;
        }
        return count;
    }

    // O(1): return the maintained size field.
    int size() {
        return size;
    }
}
